const fs=require('fs'),vm=require('vm'),assert=require('assert');
const dataset=JSON.parse(fs.readFileSync('dist/data.json'));
const nodes=new Map();
class Element{constructor(id=''){this.id=id;this.value='';this.checked=false;this.hidden=false;this.textContent='';this.classList={add(){},remove(){},toggle(){}};}set innerHTML(html){this.html=html;for(const m of html.matchAll(/<([\w-]+)\b([^>]*\bid="([^"]+)"[^>]*)>/g)){const e=new Element(m[3]),value=m[2].match(/\bvalue="([^"]*)"/);if(value)e.value=value[1];nodes.set(m[3],e);}for(const m of html.matchAll(/<textarea[^>]*id="([^"]+)"[^>]*>([\s\S]*?)<\/textarea>/g)){nodes.get(m[1]).value=m[2];}}get innerHTML(){return this.html||'';}prepend(el){this.innerHTML=el.innerHTML+this.innerHTML;}append(el){this.innerHTML+=el.innerHTML;}showModal(){}close(){} getContext(){return {drawImage(){},getImageData(){return {data:new Uint8ClampedArray(16),width:2,height:2}},putImageData(){},clearRect(){},fillRect(){}}}}
for(const id of ['app','modal','toast'])nodes.set(id,new Element(id));
const context={console,URL,Blob,Image:class{},ImageData:class{constructor(data,width,height){this.data=data;this.width=width;this.height=height;}},Uint8ClampedArray,Uint8Array,Int32Array,Date,Math,Set,Map,JSON,Number,String,Object,Array,RegExp,Infinity,document:{querySelector(s){if(s.startsWith('#'))return nodes.get(s.slice(1))||null;return new Element()},querySelectorAll(){return []},documentElement:{},hidden:false,createElement(){return new Element()}},localStorage:{getItem(){return 'en'},setItem(){}},navigator:{},window:{addEventListener(){},scrollTo(){}},setInterval(){},clearInterval(){},setTimeout(){},fetch:async path=>({ok:true,json:async()=>JSON.parse(fs.readFileSync('dist/'+path)),text:async()=>fs.readFileSync('dist/'+path,'utf8')})};
vm.createContext(context);vm.runInContext(fs.readFileSync('dist/engine.js','utf8'),context);context.AEI=context.window.AEI;let source=fs.readFileSync('dist/microbelog.js','utf8').replace(/init\(\);\s*$/,'');vm.runInContext(source,context);vm.runInContext(fs.readFileSync('dist/extensions.js','utf8'),context);
async function run(){await vm.runInContext('init()',context);assert(nodes.get('content').innerHTML.includes('Antibiotic resistance'));for(const lang of ['en','fi'])for(const v of ['overview','signals','patients','growth','explorer','images','research','chat','methods','comparisons','forecasts','directory']){await vm.runInContext(`lang='${lang}';view='${v}';render()`,context);const html=nodes.get('content').innerHTML;assert(html.length>100,lang+'/'+v);assert(!html.includes('undefined'),lang+'/'+v+' undefined');if(v==='research')assert(nodes.get('r-code').value.includes('\nprint(stats)'),'R code has actual newlines');}
await vm.runInContext("lang='en';view='chat';askQuestion('Ampicillin resistance in E. coli urine')",context);assert(vm.runInContext('chatHistory.at(-1).text.includes("45.9%")',context));await vm.runInContext("lang='fi';askQuestion('Näytä potilas P000001')",context);assert.equal(vm.runInContext('pendingPatient',context),'P000001');
assert(vm.runInContext("rateBlock({n:29,r:10,s:19,rate:10/29}).includes('Too few results')",context)===false);vm.runInContext("lang='en'",context);assert(vm.runInContext("rateBlock({n:29,r:10,s:19,rate:10/29}).includes('Too few results')",context));assert(vm.runInContext("rateBlock({n:30,r:10,s:20,rate:10/30}).includes('33.3%')",context));
const pix=new Uint8ClampedArray(4*9);for(const n of [0,1,8])pix[n*4]=255;context.testPixels=pix;const objects=vm.runInContext('connectedObjects(testPixels,3,3,1)',context);assert.deepEqual(Array.from(objects,o=>o.area_pixels),[2,1]);
const report=vm.runInContext("AEI.compute(data,{...f,institution:'hospital',care:'in',ward:'ALL',organism:'ALL',specimen:'ALL'})",context);assert(report.recent.every(r=>r[17]==='hospital'&&r[18]==='in'));assert(vm.runInContext('projectQuarters([{complete:true,n:40,r:20,x:8000}]).length===0',context));assert(vm.runInContext('projectQuarters(Array.from({length:4},(_,i)=>({complete:true,n:40,r:i*10,x:8000+i}))).every(p=>p.rate>0&&p.rate<1)',context));assert(vm.runInContext("directoryMatches({patient_id:'P1'},{culture_id:'C1'},[{isolate_id:'I1'}],[{isolate_id:'I1',result:'R'}],{test_result:'R'})",context));assert(!vm.runInContext("directoryMatches({patient_id:'P1'},{culture_id:'C1'},[{isolate_id:'I1'}],[{isolate_id:'I2',result:'R'}],{test_result:'R'})",context));console.log('PASS: 24 bilingual workspace renders, real-data chat, patient links, image-region analysis and advanced cohort filters.');}
run().catch(e=>{console.error(e);process.exit(1)});
